python
def pairedDrawersThresholdFile(drawers, k):
    a=drawers
    out=[]
    i=j=0
    while i<len(a[0]) or j<len(a[1]):
        if j==len(a[1]) or (i<len(a[0]) and a[0][i]<=a[1][j]):
            out.append(a[0][i])
            i+=1
        else:
            out.append(a[1][j])
            j+=1
    return sum(x>=k for x in out)


java
class Solution {
  public int pairedDrawersThresholdFile(int[][] drawers, int k) {
    int[][] a=drawers; List<Integer> out=new ArrayList<>();
    {int i=0,j=0;while(i<a[0].length||j<a[1].length){if(j==a[1].length||(i<a[0].length&&a[0][i]<=a[1][j]))out.add(a[0][i++]);else out.add(a[1][j++]);}}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
  }
}
